  it('composes the Slot ref and the child ref onto the same node', () => {
    const slotRef = vi.fn();
    const childRef = vi.fn();
    render(
      <Slot ref={slotRef}>
        <button ref={childRef} type="button">
          hi
        </button>
      </Slot>,
    );

    const button = screen.getByRole('button');
    expect(slotRef).toHaveBeenCalledWith(button);
    expect(childRef).toHaveBeenCalledWith(button);
  });

  it('does not alter the child ref when no ref is passed to the Slot', async () => {
    const childRef = vi.fn();

    function Repro() {
      const [text, setText] = React.useState('');
      return (
        <div>
          <input value={text} onChange={(e) => setText(e.target.value)} />
          <Slot>
            <button ref={childRef} type="button">
              hi
            </button>
          </Slot>
        </div>
      );
    }

    render(<Repro />);
    const button = screen.getByRole('button');
    // Child ref attaches to the node...
    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenLastCalledWith(button);

    // ...and stays attached (not detached/re-attached) across re-renders.
    await userEvent.type(screen.getByRole('textbox'), 'a');

    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenLastCalledWith(button);
    expect(childRef).not.toHaveBeenCalledWith(null);
  });
});

